// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _am) public {
        // Bound _am to a reasonable range
        uint256 am = bound(_am, 0, 100 ether);
        // Give the contract some ETH to avoid out-of-fund issues
        vm.deal(address(c), 10 ether);
        // Call Collect with the fuzzed amount
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));
        // The only assertion: MinSum must be 1 ether regardless of the call outcome
        assertTrue(c.MinSum() == 1 ether);
    }
}

